SELECT role.id, menu.id, function.id, tree.id
FROM bifrost_role role,
     bifrost_function function,
     bifrost_menu menu,
     bifrost_custom_tree tree
WHERE role.name IN ('运营管理部经办人')
  and function.code like 'filing%'
  and menu.name = '资料归档'
  and tree.name = '档案管理';

SELECT role.id, menu.id, function.id, tree.id
FROM bifrost_role role,
     bifrost_function function,
     bifrost_menu menu,
     bifrost_custom_tree tree
WHERE role.name IN ('项目经理')
  and function.code like 'filing%' and function.path not in ('/file/upload','/file/batch/remove')
  and menu.name = '资料归档'
  and tree.name = '档案管理';